export const getEggGroups = (pokemonName: string): string[] => {
    const cleanName = pokemonName.toLowerCase().replace(/[^a-z0-9]/g, '');
    return EGG_GROUPS_MAP[cleanName] || ['No Eggs Discovered'];
};
